const item = $input.first().json;
let datos = {};
try { datos = JSON.parse(item.datos_parciales || '{}'); } catch (e) { datos = {}; }
return [{
  json: {
    chat_id: item.chat_id,
    telegram_user: item.telegram_user,
    text: (item.text || '').trim(),
    paso_actual: item.paso_actual || '',
    id_estudiante: datos.id_estudiante || '',
    nombre_estudiante: datos.nombre_estudiante || '',
    materia: datos.materia || '',
    fecha: datos.fecha || '',
    materias_disponibles: datos.materias_disponibles || [],
    opciones: datos.opciones || []
  }
}];

const estudiante = $('Buscar Estudiante').first().json;
const materiasRows = $input.all().map(i => i.json);
const lista = materiasRows.map((m, idx) => `${idx+1}. ${m.nombre_materia}`).join('\n');
const materias_disponibles = materiasRows.map(m => ({ id_materia: m.id_materia, nombre_materia: m.nombre_materia }));
return [{
  json: {
    chat_id: $('Parsear Datos Parciales').item.json.chat_id,
    telegram_user: $('Parsear Datos Parciales').item.json.telegram_user,
    id_estudiante: estudiante.id_estudiante || '',
    nombre_estudiante: estudiante.nombre || '',
    mensaje_materias: 'Elige una materia escribiendo el numero:\n' + lista,
    datos_parciales_json: JSON.stringify({ id_estudiante: estudiante.id_estudiante || '', nombre_estudiante: estudiante.nombre || '', materias_disponibles })
  }
}];

const item = $input.first().json;
const idx = parseInt((item.text || '').trim(), 10) - 1;
const materias = item.materias_disponibles || [];
const valido = !isNaN(idx) && idx >= 0 && idx < materias.length;
const materiaElegida = valido ? materias[idx] : null;
return [{ json: { ...item, materia_valida: valido, materia_nombre: materiaElegida ? materiaElegida.nombre_materia : '' } }];

const item = $input.first().json;
const materiaNombre = item.materia_nombre || '';
const datos = { id_estudiante: item.id_estudiante, nombre_estudiante: item.nombre_estudiante, materia: materiaNombre };
return [{ json: { ...item, materia_nombre: materiaNombre, datos_parciales_json: JSON.stringify(datos) } }];

const item = $input.first().json;
const fecha = (item.text || '').trim();
const regex = /^\d{4}-\d{2}-\d{2}$/;
let valido = regex.test(fecha);
let dia_semana = '';
if (valido) {
  const d = new Date(fecha + 'T00:00:00');
  if (isNaN(d.getTime())) {
    valido = false;
  } else {
    const dias = ['Domingo','Lunes','Martes','Miercoles','Jueves','Viernes','Sabado'];
    dia_semana = dias[d.getDay()];
    const hoy = new Date();
    hoy.setHours(0,0,0,0);
    if (d < hoy) valido = false;
  }
}
return [{ json: { ...item, fecha, fecha_valida: valido, dia_semana } }];

const materia = ($('Validar Fecha').item.json.materia || '').trim().toLowerCase();
const tutores = $input.all().map(i => i.json).filter(t => {
  const estadoOk = (t.estado || '').trim().toLowerCase() === 'activo';
  const materias = (t.especialidad_materia || t.especialidad_materias || '').split(',').map(s => s.trim().toLowerCase());
  return estadoOk && materias.includes(materia);
});
return [{ json: { tutores_json: JSON.stringify(tutores) } }];

const tutores = JSON.parse($('Filtrar Tutores por Materia').item.json.tutores_json);
const tutorIds = tutores.map(t => t.id_tutor);
const base = $('Validar Fecha').item.json;
const diaSemana = (base.dia_semana || '').trim().toLowerCase();
const disponibilidad = $input.all().map(i => i.json).filter(d => {
  const estadoOk = (d.estado || '').trim().toLowerCase() === 'libre';
  const diaOk = (d.dia_semana || '').trim().toLowerCase() === diaSemana;
  return estadoOk && diaOk && tutorIds.includes(d.id_tutor);
});
const opciones = disponibilidad.map(d => {
  const t = tutores.find(t => t.id_tutor === d.id_tutor);
  return { id_dispo: d.id_dispo, id_tutor: d.id_tutor, nombre_tutor: t ? t.nombre : '', dia_semana: d.dia_semana, hora_inicio: d.hora_inicio, hora_fin: d.hora_fin };
});
return [{ json: {
  chat_id: base.chat_id,
  telegram_user: base.telegram_user,
  id_estudiante: base.id_estudiante,
  nombre_estudiante: base.nombre_estudiante,
  materia: base.materia,
  fecha: base.fecha,
  opciones,
  hay_opciones: opciones.length > 0,
  datos_parciales_json: JSON.stringify({ id_estudiante: base.id_estudiante, nombre_estudiante: base.nombre_estudiante, materia: base.materia })
} }];

const cruzado = $('Cruzar Disponibilidad').item.json;
const opciones = cruzado.opciones;
const lista = opciones.map((o, idx) => `${idx+1}. ${o.nombre_tutor} - ${o.dia_semana} ${o.hora_inicio} a ${o.hora_fin}`).join('\n');
return [{ json: {
  chat_id: cruzado.chat_id,
  telegram_user: cruzado.telegram_user,
  mensaje_opciones: 'Estas son las opciones disponibles, escribe el numero para elegir:\n' + lista,
  datos_parciales_json: JSON.stringify({ id_estudiante: cruzado.id_estudiante, nombre_estudiante: cruzado.nombre_estudiante, materia: cruzado.materia, fecha: cruzado.fecha, opciones })
} }];

const item = $input.first().json;
const idx = parseInt((item.text || '').trim(), 10) - 1;
const opciones = item.opciones || [];
const valido = !isNaN(idx) && idx >= 0 && idx < opciones.length;
const elegida = valido ? opciones[idx] : null;
return [{ json: { ...item, opcion_valida: valido, opcion_elegida: elegida } }];

const item = $input.first().json;
const opcion = item.opcion_elegida;
const id_tutoria = 'TUT-' + Date.now().toString(36).toUpperCase();
return [{ json: {
  chat_id: item.chat_id,
  telegram_user: item.telegram_user,
  id_estudiante: item.id_estudiante,
  nombre_estudiante: item.nombre_estudiante,
  materia: item.materia,
  fecha: item.fecha,
  id_tutor: opcion.id_tutor,
  nombre_tutor: opcion.nombre_tutor,
  id_dispo: opcion.id_dispo,
  hora_inicio: opcion.hora_inicio,
  hora_fin: opcion.hora_fin,
  id_tutoria
} }];

const base = $('Preparar Datos Asignacion').item.json;
const tutorRow = $input.first().json;
return [{ json: { ...base, tutor_chat_id: tutorRow.telegram_user || '' } }];

const fila = $input.first().json;
const sigueLibre = (fila.estado || '').trim().toLowerCase() === 'libre';
return [{ json: { ...$('Preparar Datos Asignacion').item.json, sigue_libre: sigueLibre } }];
